// Instanzwerte aus sub-einstellungen (Data Table pw_config, gepflegt in der
// n8n-Oberfläche unter "Data Tables").
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return String(v).trim();
};

// Das Ereignis von Paper-Werk (docs/webhooks.md in paper-werk-app).
const ereignis = $('Webhook').first().json.body ?? {};
const beleg = ereignis.beleg ?? {};

// Fachlich: nach wie vielen Tagen nachgefasst wird.
const NACHFASS_TAGE = 14;

// Fängt eine zu weit gefasste Regel und den Testaufruf ("test") ab.
if (ereignis.aktion !== 'versendet' || beleg.typ !== 'angebot') return [];

return [{ json: {
  paperwerk_url: String(pw('paperwerk_url')).replace(/\/+$/, ''),
  mail_betrieb: pw('mail_betrieb'),
  mail_absender: pw('mail_absender'),
  nachfass_tage: NACHFASS_TAGE,
  beleg,
} }];

const euro = (v) => Number(v ?? 0).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' });
const datum = (iso) => (iso ? String(iso).slice(0, 10).split('-').reverse().join('.') : '');
const html = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const TYPEN_TEXT = { angebot: 'Angebot', auftrag: 'Auftrag', lieferschein: 'Lieferschein', rechnung: 'Rechnung', storno: 'Stornorechnung', gutschrift: 'Rechnungskorrektur', mahnung: 'Mahnung' };
const typText = (typ) => TYPEN_TEXT[typ] ?? typ;

const cfg = $('Konfiguration').first().json;
const b = cfg.beleg;
// Ein Nachfolger heißt: Das Angebot ist angenommen oder abgerechnet.
if (($input.first().json.count ?? 0) > 0) return [];

const kunde = b.kunde?.name ?? 'ohne Kunde';
return [{ json: {
  fromEmail: cfg.mail_absender,
  toEmail: cfg.mail_betrieb,
  subject: `Angebot ${b.nummer} nachfassen: ${kunde}`,
  html: `<p>Das Angebot <b>${html(b.nummer)}</b> an ${html(kunde)} ist seit ${cfg.nachfass_tage} Tagen versendet, und es gibt noch keinen Auftrag dazu.</p>
<p>Betreff: ${html(b.betreff)}<br>Betrag: ${euro(b.brutto)}</p>
<p><a href="${html(b.admin_url)}">Angebot in Paper-Werk öffnen</a></p>`,
} }];
